// Discovers the launcher layers generated by Expo without targeting Android backgrounds.
import { join } from "node:path";
import type { ExportedConfig } from "expo/config-plugins";
import type { IconTarget } from "./targets";

const DENSITIES = ["mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi"];

export function findAndroidIconTargets(
  config: ExportedConfig,
  projectRoot: string
): IconTarget[] {
  const adaptiveIcon = config.android?.adaptiveIcon;
  if (!(config.android?.icon || config.icon || adaptiveIcon?.foregroundImage)) {
    return [];
  }
  return DENSITIES.flatMap((density) => {
    const directory = join(
      projectRoot,
      "android/app/src/main/res",
      `mipmap-${density}`
    );
    const targets: IconTarget[] = [
      { path: join(directory, "ic_launcher.webp"), surface: "square" },
      {
        path: join(directory, "ic_launcher_foreground.webp"),
        surface: "adaptive-foreground",
      },
    ];
    if (adaptiveIcon) {
      targets.push({
        path: join(directory, "ic_launcher_round.webp"),
        surface: "round",
      });
    }
    if (adaptiveIcon?.monochromeImage) {
      targets.push({
        path: join(directory, "ic_launcher_monochrome.webp"),
        surface: "monochrome",
      });
    }
    return targets;
  });
}
